ee:variables.ee:set-variable:
if(!isEmpty(attributes.queryParams.state))(
	"select count(*) as count, case_type, state from innodb.cvd_case_master where upper(state) = '" ++ upper(attributes.queryParams.state) ++ "' group by case_type, state"
)else(
	"select count(*) as count, case_type, state from innodb.cvd_case_master group by case_type, state"
)
